#include<limits.h>
/*@
assigns \nothing;
ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();
#define N 100000
#define fun bAnd
#include <assert.h>
/*@
  requires N >= 1;
  requires \valid_read(x + (0 .. N - 1));
  requires \forall integer k; 0 <= k < N ==> INT_MIN <= x[k] < INT_MAX;
  assigns \nothing;
  ensures \forall integer k; 0 <= k < N ==> (\result & x[k]) == \result;
  ensures \forall integer v; (\forall integer k; 0 <= k < N ==> (v & x[k]) == v) ==> (v & \result) == v;
*/
int bAnd (int x[N])
{
  int i;
  long long res;
  res = x[0];
/*@
  loop invariant 1 <= i <= N;
  loop invariant INT_MIN <= res < INT_MAX;
  loop invariant \forall integer k; 0 <= k < i ==> (res & x[k]) == res;
  loop invariant \forall integer v; (\forall integer k; 0 <= k < i ==> (v & x[k]) == v) ==> (v & res) == v;
  loop assigns i, res;
  loop variant N - i;
*/
  for (i = 1; i < N; i++) {
    res = res & x[i];
  }
  return res;
}
int main ()
{
  int x[N];
  int temp;
  int ret;
  int ret2;
  int ret5;
/*@
  loop invariant 0 <= i <= N;
  loop invariant \forall integer j; 0 <= j < i ==> INT_MIN <= x[j] < INT_MAX;
  loop assigns i, x[0 .. N - 1];
  loop variant N - i;
*/
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  ret = fun(x);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  ret2 = fun(x);
  temp=x[0];
/*@
  loop invariant 0 <= i <= N - 1;
  loop invariant temp == \at(x[0], Pre);
  loop invariant \forall integer j; 0 <= j < i ==> x[j] == \at(x[j + 1], Pre);
  loop invariant \forall integer j; i <= j < N ==> x[j] == \at(x[j], Pre);
  loop assigns i, x[0 .. N - 2];
  loop variant N - 1 - i;
*/
  for(int i =0 ; i<N-1; i++){
     x[i] = x[i+1];
  }
  x[N-1] = temp;
  ret5 = fun(x);
  //@ assert !(ret != ret2 || ret !=ret5);
  return 1;
}
